import json


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _parse_object(text):
    def _reject(name):
        raise ValueError('invalid JSON number constant: %s' % name)
    try:
        data = json.loads(text, parse_constant=_reject)
    except ValueError as exc:
        raise ValueError('invalid event JSON string') from exc
    if not isinstance(data, dict):
        raise ValueError('decoded event must be an object')
    return data


def _decode_event(raw):
    if isinstance(raw, dict):
        obj = raw
    elif isinstance(raw, str):
        obj = _parse_object(raw)
    else:
        raise ValueError('event must be an object or a JSON string')

    # partition (new field wins; invalid new field must not fall back to old)
    if 'partition' in obj:
        partition = obj['partition']
        if not isinstance(partition, str) or not partition.strip():
            raise ValueError('partition must be a non-empty string')
    elif 'topic' in obj:
        partition = obj['topic']
        if not isinstance(partition, str) or not partition.strip():
            raise ValueError('topic must be a non-empty string')
    else:
        raise ValueError('event missing partition/topic')

    # offset (new field wins)
    if 'offset' in obj:
        offset = obj['offset']
        if not _is_int(offset) or offset < 0:
            raise ValueError('offset must be a non-negative integer')
    elif 'sequence' in obj:
        offset = obj['sequence']
        if not _is_int(offset) or offset < 0:
            raise ValueError('sequence must be a non-negative integer')
    else:
        raise ValueError('event missing offset/sequence')

    # epoch (new field wins; default 0 when both absent)
    if 'epoch' in obj:
        epoch = obj['epoch']
        if not _is_int(epoch) or epoch < 0:
            raise ValueError('epoch must be a non-negative integer')
    elif 'generation' in obj:
        epoch = obj['generation']
        if not _is_int(epoch) or epoch < 0:
            raise ValueError('generation must be a non-negative integer')
    else:
        epoch = 0

    # committed (new field wins; default false when both absent)
    if 'committed' in obj:
        committed = obj['committed']
        if not isinstance(committed, bool):
            raise ValueError('committed must be a boolean')
    elif 'ack' in obj:
        committed = obj['ack']
        if not isinstance(committed, bool):
            raise ValueError('ack must be a boolean')
    else:
        committed = False

    return {'partition': partition, 'offset': offset, 'epoch': epoch, 'committed': committed}


