import json
from pathlib import Path


def _reject_constant(name):
    raise ValueError('invalid JSON number constant: %s' % name)


def load_payload(path):
    """Read a UTF-8 JSON file; the top level must be an object or an array."""
    path = Path(path)
    try:
        text = path.read_text(encoding='utf-8')
    except (OSError, UnicodeDecodeError) as exc:
        raise ValueError('failed to read payload file: %s' % path) from exc
    try:
        data = json.loads(text, parse_constant=_reject_constant)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid JSON in payload file: %s' % path) from exc
    if not isinstance(data, (dict, list)):
        raise ValueError('payload top level must be an object or array')
    return data

def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _checkpoint(obj):
    if not isinstance(obj, dict):
        raise ValueError('checkpoint must be an object')
    for key in ('partition', 'offset', 'epoch'):
        if key not in obj:
            raise ValueError('checkpoint missing %s' % key)
    partition = obj['partition']
    if not isinstance(partition, str) or not partition.strip():
        raise ValueError('checkpoint partition must be a non-empty string')
    offset = obj['offset']
    if not _is_int(offset) or offset < -1:
        raise ValueError('checkpoint offset must be an integer >= -1')
    epoch = obj['epoch']
    if not _is_int(epoch) or epoch < 0:
        raise ValueError('checkpoint epoch must be an integer >= 0')
    return partition, offset, epoch


def _event(obj):
    if not isinstance(obj, dict):
        raise ValueError('event must be an object')
    for key in ('partition', 'offset', 'epoch', 'committed'):
        if key not in obj:
            raise ValueError('event missing %s' % key)
    partition = obj['partition']
    if not isinstance(partition, str) or not partition.strip():
        raise ValueError('event partition must be a non-empty string')
    offset = obj['offset']
    if not _is_int(offset) or offset < 0:
        raise ValueError('event offset must be an integer >= 0')
    epoch = obj['epoch']
    if not _is_int(epoch) or epoch < 0:
        raise ValueError('event epoch must be an integer >= 0')
    committed = obj['committed']
    if not isinstance(committed, bool):
        raise ValueError('event committed must be a boolean')
    return partition, offset, epoch, committed


def transform(payloads, contract):
    if not payloads:
        raise ValueError('no input payloads')
    data = payloads[0]
    if isinstance(data, dict) and set(data) == {'name', 'result'}:
        data = data['result']
    if not isinstance(data, dict):
        raise ValueError('input must be an object')
    if 'checkpoints' not in data:
        raise ValueError('missing checkpoints')
    if 'events' not in data:
        raise ValueError('missing events')

    raw_checkpoints = data['checkpoints']
    raw_events = data['events']
    if not isinstance(raw_checkpoints, list):
        raise ValueError('checkpoints must be a list')
    if not isinstance(raw_events, list):
        raise ValueError('events must be a list')

    checkpoints = [_checkpoint(o) for o in raw_checkpoints]
    events = [_event(o) for o in raw_events]

    # Validate every (partition, epoch) checkpoint version for offset conflicts,
    # even versions that would be superseded by a newer one.
    ck_by_version = {}
    for partition, offset, epoch in checkpoints:
        key = (partition, epoch)
        if key in ck_by_version:
            if ck_by_version[key] != offset:
                raise ValueError('checkpoint offset conflict for same version')
        else:
            ck_by_version[key] = offset

    # Select the checkpoint with the maximum epoch per partition.
    ck_selected = {}
    for partition, offset, epoch in checkpoints:
        if partition not in ck_selected or epoch > ck_selected[partition][0]:
            ck_selected[partition] = (epoch, offset)

    # Validate every (partition, offset, epoch) event version for committed
    # conflicts, even versions that would be superseded by a newer one.
    ev_by_version = {}
    for partition, offset, epoch, committed in events:
        key = (partition, offset, epoch)
        if key in ev_by_version:
            if ev_by_version[key] != committed:
                raise ValueError('event committed conflict for same version')
        else:
            ev_by_version[key] = committed

    # Select the maximum-epoch event per (partition, offset).
    ev_selected = {}
    for partition, offset, epoch, committed in events:
        key = (partition, offset)
        if key not in ev_selected or epoch > ev_selected[key][0]:
            ev_selected[key] = (epoch, committed)

    partitions = set()
    for partition, _, _ in checkpoints:
        partitions.add(partition)
    for partition, _, _, _ in events:
        partitions.add(partition)

    next_offsets = {}
    applied = []
    pending = {}

    for partition in sorted(partitions):
        if partition in ck_selected:
            ck_epoch, ck_offset = ck_selected[partition]
        else:
            ck_epoch, ck_offset = 0, -1

        selected = {}
        for (p, offset), (epoch, committed) in ev_selected.items():
            if p == partition:
                selected[offset] = (epoch, committed)

        cur = ck_offset + 1
        while cur in selected:
            epoch, committed = selected[cur]
            if epoch >= ck_epoch and committed is True:
                applied.append('%s:%d' % (partition, cur))
                cur += 1
                continue
            break

        next_offsets[partition] = cur
        pending[partition] = sorted(offset for offset in selected if offset >= cur)

    return {
        'name': contract['name'],
        'result': {
            'next_offsets': next_offsets,
            'applied': applied,
            'pending': pending,
        },
    }

