import json
import re


_VALID_LEVELS = {'debug', 'info', 'warn', 'error'}

_SECRET_RE = re.compile(
    r'\b(token|password|secret)\b\s*=\s*'
    r'(?:"(?:[^"\\]|\\.)*"|\'(?:[^\'\\]|\\.)*\'|[^\s,;]+)',
    re.IGNORECASE,
)


def _normalize_level(level):
    if not isinstance(level, str):
        raise ValueError('level must be a string')
    level = level.strip().lower()
    if level == 'warning':
        level = 'warn'
    if level not in _VALID_LEVELS:
        raise ValueError('invalid level: %s' % level)
    return level


def _redact(message):
    return _SECRET_RE.sub(lambda m: m.group(1).lower() + '=[REDACTED]', message)


def _process_object(obj):
    if 'level' in obj:
        level = obj['level']
    elif 'severity' in obj:
        level = obj['severity']
    else:
        raise ValueError('object line missing level/severity')

    if 'message' in obj:
        message = obj['message']
    elif 'msg' in obj:
        message = obj['msg']
    else:
        raise ValueError('object line missing message/msg')

    if not isinstance(message, str):
        raise ValueError('message must be a string')

    return _normalize_level(level), message


def _process_string(line):
    stripped = line.lstrip()
    if stripped.startswith('{'):
        def _reject(name):
            raise ValueError('invalid JSON number constant: %s' % name)
        try:
            obj = json.loads(stripped, parse_constant=_reject)
        except ValueError as exc:
            raise ValueError('invalid JSON object line') from exc
        if not isinstance(obj, dict):
            raise ValueError('JSON line must decode to an object')
        return _process_object(obj)

    text = line.strip()
    if not text:
        return None

    parts = text.split(None, 1)
    level = _normalize_level(parts[0])
    message = parts[1] if len(parts) > 1 else ''
    return level, message


def transform(payloads, contract):
    if not payloads:
        raise ValueError('no input payloads')
    data = payloads[0]
    if isinstance(data, dict) and set(data) == {'name', 'result'}:
        data = data['result']
    if not isinstance(data, dict):
        raise ValueError('input must be an object')
    if 'lines' not in data:
        raise ValueError('missing lines')

    raw_lines = data['lines']
    if not isinstance(raw_lines, list):
        raise ValueError('lines must be a list')

    out_lines = []
    counts = {}

    for raw in raw_lines:
        if isinstance(raw, dict):
            level, message = _process_object(raw)
        elif isinstance(raw, str):
            parsed = _process_string(raw)
            if parsed is None:
                continue
            level, message = parsed
        else:
            raise ValueError('line must be a string or an object')

        out_lines.append('%s %s' % (level.upper(), _redact(message)))
        counts[level] = counts.get(level, 0) + 1

    return {
        'name': contract['name'],
        'result': {
            'lines': out_lines,
            'counts': counts,
        },
    }

import json
import os
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _norm(path):
    return os.path.normpath(os.path.abspath(str(path)))


def _contracts():
    return sorted(
        p for p in ROOT.rglob('contract.json')
        if 'outputs' not in p.relative_to(ROOT).parts
    )


def main():
    contracts = _contracts()
    if not contracts:
        raise SystemExit('no component contracts found')

    # Map each component's output path back to its contract so that inputs that
    # reference another component's output create a real execution dependency.
    by_output = {}
    for cp in contracts:
        c = json.loads(cp.read_text(encoding='utf-8'))
        by_output[_norm(ROOT / c['output'])] = cp

    deps = {}
    for cp in contracts:
        c = json.loads(cp.read_text(encoding='utf-8'))
        d = []
        for inp in c['inputs']:
            norm = _norm(ROOT / inp)
            if norm in by_output and by_output[norm] != cp:
                d.append(by_output[norm])
        deps[cp] = d

    order = []
    state = {}

    def visit(cp):
        s = state.get(cp, 0)
        if s == 2:
            return
        if s == 1:
            raise SystemExit('dependency cycle detected')
        state[cp] = 1
        for dep in deps[cp]:
            visit(dep)
        state[cp] = 2
        order.append(cp)

    for cp in contracts:
        visit(cp)

    for cp in order:
        render_py = cp.parent / 'render.py'
        subprocess.run([sys.executable, str(render_py)], cwd=ROOT, check=True)

    subprocess.run([sys.executable, str(ROOT / 'integrate.py')], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / 'final_report.py')], cwd=ROOT, check=True)


if __name__ == '__main__':
    main()

